p=J/'research/Research.java';s=p.read_text();start=s.index(' public static void observe(');end=s.index(' public static void completePapers',start)
s=s[:start]+''' public static void thought(ServerPlayer p,ResearchCatalog.Node n,int step){var st=n.steps().get(step);String value=st.comment().isBlank()?"Я заметил новый след и сохранил его на листе.":st.comment();p.sendSystemMessage(Component.literal("["+name(n)+" · "+(step+1)+"/"+n.steps().size()+"] ").withStyle(net.minecraft.ChatFormatting.DARK_AQUA).append(Component.literal(value).withStyle(net.minecraft.ChatFormatting.GRAY,net.minecraft.ChatFormatting.ITALIC)));}
 public static void observe(ServerPlayer p,String signal){var s=state(p);var messages=new ArrayList<Map.Entry<ResearchCatalog.Node,Integer>>();for(String id:s.started()){var n=ResearchCatalog.BY_ID.get(id);if(n==null||n.sealed()||ResearchCatalog.learned(s,id)||!hasPaper(p,id))continue;int step=progress(s,n);if(step<n.steps().size()){var st=n.steps().get(step);if(st.kind().equals("observation")&&st.signals().contains(signal)){s=s.add("evidence",id+":"+step);messages.add(Map.entry(n,step));}}}if(!messages.isEmpty()){save(p,s);completePapers(p);for(var m:messages)thought(p,m.getKey(),m.getValue());}}
 public static boolean hasPaper(ServerPlayer p,String id){return p.getInventory().items.stream().anyMatch(s->s.is(HYPOTHESIS)&&owned(p,s)&&id.equals(s.get(MagicComponents.RESEARCH_ID.get())))||p.getOffhandItem().is(HYPOTHESIS)&&owned(p,p.getOffhandItem())&&id.equals(p.getOffhandItem().get(MagicComponents.RESEARCH_ID.get()));}
 static List<ItemStack> stocks(ServerPlayer p){var all=new ArrayList<ItemStack>(p.getInventory().items);all.addAll(p.getInventory().offhand);return all;}
 public static boolean sample(ServerPlayer p,String id){var n=ResearchCatalog.BY_ID.get(id);var s=state(p);if(n==null||n.sealed()||!s.started().contains(id)||ResearchCatalog.learned(s,id)||!hasPaper(p,id))return false;int step=progress(s,n);if(step>=n.steps().size())return false;var st=n.steps().get(step);if(!st.kind().equals("material"))return false;var needs=new LinkedHashMap<Item,Integer>();for(String key:st.samples().isEmpty()?List.of(st.item()):st.samples()){var item=BuiltInRegistries.ITEM.get(ResourceLocation.parse(key));if(item==Items.AIR)return false;needs.merge(item,1,Integer::sum);}var stocks=stocks(p);for(var need:needs.entrySet())if(stocks.stream().filter(v->v.is(need.getKey())).mapToInt(ItemStack::getCount).sum()<need.getValue())return false;for(var need:needs.entrySet()){int left=need.getValue();for(var stack:stocks)if(stack.is(need.getKey())){int take=Math.min(left,stack.getCount());stack.shrink(take);left-=take;if(left==0)break;}}save(p,s.add("evidence",id+":"+step));completePapers(p);thought(p,n,step);p.getInventory().setChanged();return true;}
 public static boolean material(ServerPlayer p,ItemStack sheet){if(!sheet.is(HYPOTHESIS)||!owned(p,sheet))return false;return sample(p,sheet.getOrDefault(MagicComponents.RESEARCH_ID.get(),""));}
 public static boolean advanceMaterialsAtTable(ServerPlayer p){boolean pending=state(p).started().stream().anyMatch(id->{var n=ResearchCatalog.BY_ID.get(id);return n!=null&&hasPaper(p,id)&&progress(state(p),n)<n.steps().size()&&n.steps().get(progress(state(p),n)).kind().equals("material");});if(!pending)return false;boolean near=false;for(var at:net.minecraft.core.BlockPos.betweenClosed(p.blockPosition().offset(-2,-1,-2),p.blockPosition().offset(2,1,2)))if(p.serverLevel().getBlockState(at).is(MagicStudy.TABLE.get())&&p.distanceToSqr(net.minecraft.world.phys.Vec3.atCenterOf(at))<=6.25){near=true;break;}if(!near)return false;boolean changed=false;for(String id:List.copyOf(state(p).started()))changed=sample(p,id)||changed;return changed;}
''' + s[end:]
